        for (int num : nums) {
            count[num]++;
        }
        auto cmp = [](const pair<int, int>& a, const pair<int, int>& b) {
            return a.second > b.second;
        };
        priority_queue<pair<int, int>, vector<pair<int, int>>, decltype(cmp)> heap(cmp);
        for (const auto& entry : count) {
            heap.push(entry);
            if ((int)heap.size() > k) {
                heap.pop();
            }
        }
        vector<int> res;
        while (!heap.empty()) {
            res.push_back(heap.top().first);
            heap.pop();
        }
        return res;
    }
};

